 setObjectName("securitiesDirectoryPage");workers.setMaxThreadCount(1);auto root=new QVBoxLayout(this);root->setContentsMargins(8,8,8,8);auto top=new QHBoxLayout;auto title=new QLabel("证券全目录",this);top->addWidget(title,1);auto back=button("返回看盘","securitiesDirectoryBack",this);top->addWidget(back);root->addLayout(top);connect(back,&QPushButton::clicked,this,[this]{if(!isVisible())return;cancel();emit backRequested();});
