 auto middle=new QWidget(split);auto ml=new QVBoxLayout(middle);ml->setContentsMargins(0,0,0,0);table=new QTableWidget(0,4,middle);table->setObjectName("securitiesDirectoryResults");table->setHorizontalHeaderLabels({"名称 / 代码","市场 / 品种","完整身份","来源 / 时刻"});table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::SingleSelection);table->verticalHeader()->hide();table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setStretchLastSection(true);ml->addWidget(table,1);auto pages=new QHBoxLayout;previous=button("上一页","securitiesDirectoryPrevious",middle);next=button("下一页","securitiesDirectoryNext",middle);pageLabel=new QLabel(middle);pageLabel->setObjectName("securitiesDirectoryPagination");pages->addWidget(previous);pages->addWidget(pageLabel,1);pages->addWidget(next);ml->addLayout(pages);
 auto right=new QWidget(split);auto rl=new QVBoxLayout(right);rl->setContentsMargins(5,0,0,0);details=new QTextBrowser(right);details->setObjectName("securitiesDirectoryDetails");details->setOpenExternalLinks(false);rl->addWidget(details,1);open=button("打开原图表","securitiesDirectoryOpen",right);research=button("打开原个股研究","securitiesDirectoryResearch",right);add=button("明确加入自选","securitiesDirectoryAdd",right);for(auto*b:{open,research,add})rl->addWidget(b);right->setMinimumWidth(160);split->setSizes({175,450,235});split->setStretchFactor(1,1);status=new QLabel(this);status->setObjectName("securitiesDirectoryStatus");status->setTextFormat(Qt::PlainText);status->setWordWrap(true);root->addWidget(status);
 debounce.setSingleShot(true);debounce.setInterval(120);connect(&debounce,&QTimer::timeout,this,[this]{searchLocal();});connect(query,&QLineEdit::textChanged,this,[this]{cancel();lookupReceipt={};selected={};matched={};searchReady=false;page=0;table->setRowCount(0);merge();controls();debounce.start();});for(auto*c:{market,type})connect(c,&QComboBox::currentIndexChanged,this,[this]{cancel();selected={};page=0;searchLocal();});connect(local,&QPushButton::clicked,this,[this]{if(isVisible())reload();});connect(previous,&QPushButton::clicked,this,[this]{if(page>0){--page;showPage();}});connect(next,&QPushButton::clicked,this,[this]{if((page+1)*100<matched.size()){++page;showPage();}});connect(table,&QTableWidget::itemSelectionChanged,this,&SecuritiesDirectoryPage::select);connect(open,&QPushButton::clicked,this,[this]{act("chart");});connect(research,&QPushButton::clicked,this,[this]{act("research");});connect(add,&QPushButton::clicked,this,[this]{act("watchlist");});connect(stop,&QPushButton::clicked,this,[this]{if(!isVisible())return;pendingLookup.clear();cancel();notice="已取消；旧目录与资料保留，不接收晚回调。";status->setText(notice);});
 connect(refresh,&QPushButton::clicked,this,[this]{if(!allowed||!isVisible()||window()->isMinimized()||loading||networkBusy)return;cancel();networkBusy=true;controls();feed->directory();});connect(deep,&QPushButton::clicked,this,[this]{if(!allowed||!isVisible()||window()->isMinimized()||loading||networkBusy||query->text().trimmed().size()<2)return;cancel();networkBusy=true;controls();try{feed->lookup(query->text().trimmed());}catch(const std::exception&e){networkBusy=false;setHostError(QString::fromUtf8(e.what()));}});connect(feed,&securitiesCatalog::Feed::progress,this,[this](QString s){if(isVisible())status->setText(s);});
 connect(feed,&securitiesCatalog::Feed::finished,this,[this](QString kind,QString q,QJsonObject result,QString error){if(!isVisible()||(kind=="search"&&q!=query->text().trimmed()))return;networkBusy=false;securitiesCatalog::Cache cache(cachePath);QJsonObject receipt;try{if(error.isEmpty())cache.save(kind,q,result);else cache.failure(kind,q,error,now());receipt=cache.read(kind,q);}catch(const std::exception&e){error=QString::fromUtf8(e.what());try{cache.failure(kind,q,error.left(1000),now());receipt=cache.read(kind,q);}catch(const std::exception&){} }if(kind=="directory"){if(!receipt.isEmpty())directoryReceipt=receipt;}else if(!receipt.isEmpty())lookupReceipt=receipt;notice=error.isEmpty()?kind=="directory"?QString("公开沪深A股与ETF文件已完整读取；BJ/指数和原资料保留。" ):QString("公开名称/代码匹配已读取；它不是完整目录。"):QString("公开读取/保存失败，旧值保留：")+error;merge();searchLocal();});
 details->setPlainText("请选择记录；身份未确认的行保留原资料，不能打开或加入自选。");controls();
