SecuritiesDirectoryPage::~SecuritiesDirectoryPage(){cancel();workers.clear();workers.waitForDone();}
void SecuritiesDirectoryPage::cancel(){++generation;cancelled->store(true);workers.clear();debounce.stop();loading=false;networkBusy=false;feed->cancel();if(status)controls();}
void SecuritiesDirectoryPage::run(std::function<QJsonObject()> work,std::function<void(QJsonObject)> done){cancelled->store(true);cancelled=std::make_shared<std::atomic_bool>(false);auto flag=cancelled;auto ticket=++generation;loading=true;controls();QPointer<SecuritiesDirectoryPage> self(this);workers.clear();workers.start([self,flag,ticket,work,done]{QJsonObject result;QString error;try{if(!flag->load())result=work();}catch(const std::exception&e){error=QString::fromUtf8(e.what());}QMetaObject::invokeMethod(qApp,[self,flag,ticket,result,error,done]{if(!self||flag->load()||self->generation!=ticket||!self->isVisible())return;self->loading=false;if(error.isEmpty())try{done(result);}catch(const std::exception&e){self->setHostError(QString::fromUtf8(e.what()));}else self->setHostError("本机读取失败，原已显示资料保留："+error);self->controls();},Qt::QueuedConnection);});}
void SecuritiesDirectoryPage::reload(){if(!isVisible())return;cancel();selected={};searchReady=false;status->setText("正在载入证券目录…" );auto path=legacyPath,publicPath=cachePath;run([path,publicPath]{SecuritiesLegacyStore store(path);auto rows=store.directory();securitiesCatalog::validateRows(rows);QJsonObject out{{"rows",rows},{"stats",store.stats()}};try{out["directory"]=securitiesCatalog::Cache(publicPath).read("directory");}catch(const std::exception&e){out["cacheError"]=QString::fromUtf8(e.what());}return out;},[this](QJsonObject r){legacyRows=r["rows"].toArray();stats=r["stats"].toObject();directoryReceipt=r["directory"].toObject();loaded=true;notice=r["cacheError"].toString();if(!stats["available"].toBool())notice="旧目录尚未导入，可刷新公开目录。";merge();searchLocal();});}
void SecuritiesDirectoryPage::merge(){allRows=legacyRows;QHash<QString,int> index;for(int i=0;i<allRows.size();++i)index.insert(allRows[i].toObject()["id"].toString(),i);for(auto receipt:{directoryReceipt,lookupReceipt}){auto result=receipt["result"].toObject();auto at=result["fetchedAt"].toString();for(auto v:result["items"].toArray()){auto r=v.toObject();auto id=r["id"].toString();int position=index.value(id,-1);if(position>=0){auto old=allRows[position].toObject();if(!old["publicFetchedAt"].toString().isEmpty()&&QDateTime::fromString(old["publicFetchedAt"].toString(),Qt::ISODateWithMs)>QDateTime::fromString(at,Qt::ISODateWithMs))continue;r["originalLocalRecord"]=old.contains("originalLocalRecord")?old["originalLocalRecord"]:QJsonValue(old);r["publicRecord"]=r;r["legacy"]=old["legacy"];r["publicFetchedAt"]=at;allRows[position]=r;}else{r["publicFetchedAt"]=at;index.insert(id,allRows.size());allRows.append(r);}}}coverage->setText(QString("旧目录 %1 项 · 当前 %2 项 · %3").arg(legacyRows.size()).arg(allRows.size()).arg(directoryReceipt["result"].toObject()["fetchedAt"].toString().isEmpty()?"尚未刷新公开目录":("公开目录读取 "+directoryReceipt["result"].toObject()["fetchedAt"].toString()+"；源时刻未知")));auto packet=directoryReceipt["result"].toObject();if(!packet.isEmpty())coverage->setText(coverage->text()+QString("\n本次公开股票 %1（沪深A股） · ETF %2（单独计数） · 股票来源：%3").arg(packet["stockCount"].toInt()).arg(packet["etfCount"].toInt()).arg(packet["stockProvider"]=="sina-a-shares"?"新浪公开沪深A股":"东财公开沪深A股"));}
void SecuritiesDirectoryPage::searchLocal(){if(!isVisible())return;if(!loaded){reload();return;}cancel();selected={};searchReady=false;page=0;table->setRowCount(0);controls();auto q=query->text().trimmed(),m=market->currentData().toString(),t=type->currentData().toString(),path=cachePath;auto rows=allRows;status->setText("正在对完整目录检索；不以自选或5000行样本替代。" );run([q,m,t,path,rows]{QJsonObject receipt;QString error;if(q.size()>=2)try{receipt=securitiesCatalog::Cache(path).read("search",q);}catch(const std::exception&e){error=QString::fromUtf8(e.what());}QJsonArray combined=rows;QHash<QString,int> seen;for(int i=0;i<combined.size();++i)seen.insert(combined[i].toObject()["id"].toString(),i);for(auto v:receipt["result"].toObject()["items"].toArray()){auto r=v.toObject();if(!seen.contains(r["id"].toString())){r["publicFetchedAt"]=receipt["result"].toObject()["fetchedAt"];combined.append(r);}}return QJsonObject{{"query",q},{"rows",securitiesCatalog::search(combined,q,m,t)},{"lookup",receipt},{"cacheError",error}};},[this,q](QJsonObject r){if(query->text().trimmed()!=q)return;matched=r["rows"].toArray();completedQuery=q;searchReady=true;lookupReceipt=r["lookup"].toObject();showPage();status->setText((notice.isEmpty()?QString("搜索完成"):notice)+(r["cacheError"].toString().isEmpty()?QString():" · 检索缓存拒绝："+r["cacheError"].toString()));});}
void SecuritiesDirectoryPage::showPage(){selected={};QSignalBlocker guard(table);table->setRowCount(0);int end=std::min((page+1)*100,int(matched.size()));for(int i=page*100;i<end;++i){auto r=matched[i].toObject();int n=table->rowCount();table->insertRow(n);auto first=new QTableWidgetItem(text(r["name"])+"\n"+text(r["code"]));first->setData(Qt::UserRole,r);table->setItem(n,0,first);table->setItem(n,1,new QTableWidgetItem(text(r["market"])+" / "+text(r["type"])));table->setItem(n,2,new QTableWidgetItem(r["canOpen"].toBool()?r["id"].toString():"身份未确认"));table->setItem(n,3,new QTableWidgetItem(r["source"].toString().isEmpty()?"旧资料\n"+text(r["legacy"].toObject()["updated_at"]):r["source"].toString()+"\n"+r["publicFetchedAt"].toString()));}pageLabel->setText(QString("%1 匹配 · %2/%3 页 · 每页100").arg(matched.size()).arg(matched.isEmpty()?0:page+1).arg((matched.size()+99)/100));details->setPlainText("请选择明确证券，查看完整原资料及身份来源。");controls();}
void SecuritiesDirectoryPage::select(){int n=table->currentRow();selected=n>=0&&table->item(n,0)?table->item(n,0)->data(Qt::UserRole).toJsonObject():QJsonObject{};if(!selected.isEmpty())details->setPlainText(text(selected["name"])+"\n"+text(selected["id"])+"\n"+text(selected["identityReason"])+"\n原记录（空值与原时刻保留）：\n"+QString::fromUtf8(QJsonDocument(selected).toJson(QJsonDocument::Indented)));controls();}
void SecuritiesDirectoryPage::controls(){bool good=false;if(!selected.isEmpty())try{auto row=securitiesCatalog::instrument(selected);stockResearch::identity(row["id"].toString());good=true;}catch(const std::exception&){}bool ready=isVisible()&&!loading&&!networkBusy;open->setEnabled(ready&&good);research->setEnabled(ready&&good);add->setEnabled(ready&&good);refresh->setEnabled(ready&&allowed);deep->setEnabled(ready&&allowed&&query->text().trimmed().size()>=2);stop->setEnabled(loading||networkBusy);previous->setEnabled(!loading&&page>0);next->setEnabled(!loading&&(page+1)*100<matched.size());if(ready&&loaded&&searchReady&&!debounce.isActive()&&completedQuery==query->text().trimmed()&&!pendingLookup.isEmpty()){auto q=pendingLookup;pendingLookup.clear();auto ticket=generation;QTimer::singleShot(0,this,[this,q,ticket]{if(ticket==generation&&isVisible()&&q==query->text().trimmed()&&deep->isEnabled())deep->click();});}}
void SecuritiesDirectoryPage::act(QString action){if(!isVisible()||window()->isMinimized()||loading||networkBusy)return;try{auto row=securitiesCatalog::instrument(selected);stockResearch::identity(row["id"].toString());emit actionRequested(row,action);}catch(const std::exception&e){setHostError(QString::fromUtf8(e.what()));}}
void SecuritiesDirectoryPage::setHostError(const QString&s){notice=s;status->setText(s);controls();}
QJsonObject SecuritiesDirectoryPage::sourceEvidence()const{QJsonArray visible;for(int i=0;i<table->rowCount();++i)visible.append(table->item(i,0)->data(Qt::UserRole).toJsonObject());return {{"loaded",loaded},{"loading",loading},{"legacyRows",legacyRows.size()},{"directoryRows",allRows.size()},{"matchedRows",matched.size()},{"query",query->text().trimmed()},{"completedQuery",completedQuery},{"searchReady",searchReady},{"market",market->currentData().toString()},{"type",type->currentData().toString()},{"page",page},{"visibleRows",visible},{"selected",selected},{"legacyStats",stats},{"publicDirectory",receiptEvidence(directoryReceipt)},{"publicLookup",receiptEvidence(lookupReceipt)}};}
QJsonObject SecuritiesDirectoryPage::saveState()const{return {{"schema","native-securities-directory-ui/v1"},{"query",query->text()},{"market",market->currentData().toString()},{"type",type->currentData().toString()}};}
void SecuritiesDirectoryPage::restoreState(const QJsonObject&r){if(r["schema"]!="native-securities-directory-ui/v1")return;cancel();searchReady=false;QSignalBlocker a(query),b(market),c(type);query->setText(r["query"].toString().left(60));int m=market->findData(r["market"].toString()),t=type->findData(r["type"].toString());if(m>=0)market->setCurrentIndex(m);if(t>=0)type->setCurrentIndex(t);if(isVisible())searchLocal();}
void SecuritiesDirectoryPage::hideEvent(QHideEvent*e){pendingLookup.clear();cancel();QWidget::hideEvent(e);}
void SecuritiesDirectoryPage::setSharedQuery(const QString& text,bool online){query->hide();query->setMaxLength(32767);pendingLookup.clear();query->setText(text);if(online&&text.trimmed().size()>=2)pendingLookup=text.trimmed();controls();}
void SecuritiesDirectoryPage::setCompactList(){
 auto* split=findChild<QSplitter*>();if(split){split->widget(0)->hide();split->widget(2)->hide();}
 coverage->hide();table->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);for(int c=1;c<table->columnCount();++c)table->setColumnHidden(c,true);
 for(auto* b:findChildren<QPushButton*>())if(b!=previous&&b!=next){b->hide();b->setProperty("settingsControl",true);}
 connect(table,&QTableWidget::cellClicked,this,[this](int,int){act("chart");});
}
void SecuritiesDirectoryPage::showEvent(QShowEvent*e){QWidget::showEvent(e);if(!loaded)reload();else if(!searchReady||completedQuery!=query->text().trimmed())searchLocal();else controls();}
